use std :: sync :: Arc ; use colored :: Colorize ; use forge_api :: API ; use forge_config :: { Update , UpdateFrequency } ; use forge_select :: ForgeWidget ; use forge_tracker :: VERSION ; use update_informer :: { Check , Version , registry } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Checks if there is an update available"] pub async fn on_update (api : Arc < impl API > , update : Option < & Update >) { let update = update . cloned () . unwrap_or_default () ; let frequency = update . frequency . unwrap_or_default () ; if ! should_check_for_updates (& frequency) { return ; } let auto_update = update . auto_update . unwrap_or_default () ; if VERSION . contains ("dev") || VERSION == "0.1.0" { return ; } let informer = update_informer :: new (registry :: GitHub , "tailcallhq/forgecode" , VERSION) . interval (frequency . into ()) ; if let Some (version) = informer . check_version () . ok () . flatten () && (auto_update || confirm_update (version) . await) { execute_update_command (api , auto_update) . await ; } }